contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint times) public payable {
        require(address(this).balance >= amount);
        uint before = c.depositsCount();
        for (uint i = 0; i < times && i < 3; i++) {
            c.fallback{value: amount}();
        }
        uint after_ = c.depositsCount();
        assert(after_ == before + (times < 3 ? times : 3));
    }
    receive() external payable {}
}

